<?php
$h = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
$url = static fn(string $query): string => stat_url($query);
?>
<main class="sl-learn sl-learn-lesson" dir="rtl">
    <nav class="sl-learn-breadcrumb"><a href="<?= $h($url('controller=learn')) ?>">مرکز آموزش</a><span>/</span><span><?= $h($lesson['title']) ?></span></nav>
    <header class="sl-learn-hero sl-learn-hero--lesson"><div><span class="sl-learn-kicker"><?= $h($levelLabel) ?> · <?= (int) $lesson['minutes'] ?> دقیقه</span><h1><i class="<?= $h($lesson['icon']) ?>" aria-hidden="true"></i> <?= $h($lesson['title']) ?></h1><p><?= $h($lesson['summary']) ?></p></div></header>
    <details class="sl-learn-toc"><summary>فهرست این درس <i class="fas fa-chevron-down" aria-hidden="true"></i></summary><ol><?php foreach ($lesson['sections'] as $i => $section): ?><li><a href="#section-<?= $i ?>"><?= $h($section['h']) ?></a></li><?php endforeach; ?><li><a href="#formulas">فرمول‌ها</a></li><li><a href="#example">مثال حل‌شده</a></li><li><a href="#practice">تمرین</a></li></ol></details>
    <?php foreach ($lesson['sections'] as $i => $section): ?>
        <section class="sl-learn-panel" id="section-<?= $i ?>"><h2><span><?= sprintf('%02d', $i + 1) ?></span><?= $h($section['h']) ?></h2><?php foreach ($section['p'] as $paragraph): ?><p><?= $h($paragraph) ?></p><?php endforeach; ?><?php if (!empty($section['list'])): ?><ul><?php foreach ($section['list'] as $item): ?><li><?= $h($item) ?></li><?php endforeach; ?></ul><?php endif; ?></section>
    <?php endforeach; ?>
    <?php if (!empty($lesson['formulas'])): ?><section class="sl-learn-panel" id="formulas"><h2><span><i class="fas fa-square-root-variable"></i></span>فرمول‌ها و نکته‌ها</h2><div class="sl-learn-formulas"><?php foreach ($lesson['formulas'] as $formula): ?><article><h3><?= $h($formula['name']) ?></h3><code dir="ltr"><?= $h($formula['expr']) ?></code><p><?= $h($formula['note']) ?></p></article><?php endforeach; ?></div></section><?php endif; ?>
    <?php if (!empty($lesson['example'])): ?><section class="sl-learn-panel sl-learn-example" id="example"><h2><span><i class="fas fa-lightbulb"></i></span><?= $h($lesson['example']['title']) ?></h2><p><strong>داده‌های مسئله:</strong></p><ul><?php foreach ($lesson['example']['given'] as $given): ?><li><?= $h($given) ?></li><?php endforeach; ?></ul><div class="sl-learn-steps"><?php foreach ($lesson['example']['steps'] as $step): ?><article><strong><?= $h($step['label']) ?></strong><code dir="ltr"><?= $h($step['math']) ?></code><span><?= $h($step['result']) ?></span></article><?php endforeach; ?></div><p class="sl-learn-answer"><?= $h($lesson['example']['answer']) ?></p></section><?php endif; ?>
    <?php if (!empty($lesson['pitfalls'])): ?><section class="sl-learn-panel sl-learn-pitfalls"><h2><span><i class="fas fa-triangle-exclamation"></i></span>خطاهای رایج</h2><ul><?php foreach ($lesson['pitfalls'] as $item): ?><li><?= $h($item) ?></li><?php endforeach; ?></ul></section><?php endif; ?>
    <?php if (!empty($lesson['practice'])): ?><details class="sl-learn-panel sl-learn-practice" id="practice"><summary><h2><span><i class="fas fa-pen-to-square"></i></span>تمرین: <?= $h($lesson['practice']['q']) ?></h2></summary><p><?= $h($lesson['practice']['a']) ?></p></details><?php endif; ?>
    <nav class="sl-learn-pager" aria-label="جابجایی بین درس‌ها"><a href="<?= $h($url('controller=learn')) ?>"><i class="fas fa-list"></i> فهرست درس‌ها</a><?php if ($previous): ?><a href="<?= $h($url('controller=learn&action=show&lesson=' . rawurlencode($previous['id']))) ?>">درس قبل: <?= $h($previous['title']) ?></a><?php endif; ?><?php if ($next): ?><a class="sl-learn-pager__next" href="<?= $h($url('controller=learn&action=show&lesson=' . rawurlencode($next['id']))) ?>">درس بعد: <?= $h($next['title']) ?> <i class="fas fa-arrow-left"></i></a><?php endif; ?></nav>
</main>
